// :core is plain Kotlin/JVM with no android.* dependency: protocol,
// crypto, pairing, sync and event reduction, all testable on the JVM.
plugins {
    alias(libs.plugins.kotlin.jvm)
}

kotlin {
    jvmToolchain(17)
}

sourceSets {
    test { kotlin.srcDir(rootProject.file("../testdata/projection/kotlin")) }
    main {
        // Generated by `buf generate` in android/, see buf.gen.yaml.
        java.srcDir("src/main/gen")
        kotlin.srcDir("src/main/gen")
    }
}

dependencies {
    api(libs.protobuf.javalite)
    // connect-kotlin declares moshi-kotlin, the reflective adapter factory,
    // but reads its JSON with generated adapters, which need Moshi alone.
    // See LiteProtobuf.kt for why kotlin-reflect is kept out.
    api(libs.connect.okhttp) {
        exclude(group = "com.squareup.moshi", module = "moshi-kotlin")
        exclude(group = "org.jetbrains.kotlin", module = "kotlin-reflect")
    }
    runtimeOnly(libs.moshi)
    api(libs.okhttp)
    api(libs.coroutines.core)
    implementation(libs.bouncycastle)

    testImplementation(libs.junit)
    testImplementation(libs.coroutines.test)
    implementation(libs.serialization.json)
}

// The integration tests run against the real Go server. Without Go on the
// PATH they are skipped.
val testServer = layout.buildDirectory.file("ra-server").get().asFile
val repoRoot = rootProject.file("..")
val buildTestServer by tasks.registering(Exec::class) {
    workingDir = repoRoot
    commandLine("go", "build", "-o", testServer.absolutePath, "./internal/testutil/relaytestserver")
    onlyIf { System.getenv("PATH").orEmpty().split(File.pathSeparator).any { File(it, "go").canExecute() } }
}

val testSecurityFixture=layout.buildDirectory.file("ra-security-fixture").get().asFile
val buildTestSecurityFixture by tasks.registering(Exec::class){
 workingDir=repoRoot
 commandLine("go","build","-o",testSecurityFixture.absolutePath,"./internal/testutil/securityfixture")
 onlyIf { System.getenv("PATH").orEmpty().split(File.pathSeparator).any { File(it,"go").canExecute() } }
}
tasks.test {
    dependsOn(buildTestServer,buildTestSecurityFixture)
    systemProperty("raSecurityFixture",testSecurityFixture.absolutePath)
    systemProperty("raServer", testServer.absolutePath)
    // The test vectors are shared with Go and TypeScript.
    inputs.file(rootProject.file("../testdata/projection/vectors.json")).withPathSensitivity(PathSensitivity.NONE)
    systemProperty("projectionVectors", rootProject.file("../testdata/projection/vectors.json").absolutePath)
    systemProperty("vectors", rootProject.file("../internal/e2e/testdata/vectors.json").absolutePath)
    systemProperty("completionVectors",rootProject.file("../internal/deviceauth/testdata/revocation-v2.json").absolutePath)
    systemProperty("domainVectors", rootProject.file("../internal/deviceauth/testdata/domain-v3.json").absolutePath)
    systemProperty("v3Vectors", rootProject.file("../internal/e2e/testdata/v3-vectors.json").absolutePath)
    systemProperty("recoveryVectors", rootProject.file("../internal/deviceauth/testdata/recovery-v3.json").absolutePath)
    systemProperty("recoveryRemovedVectors", rootProject.file("../internal/deviceauth/testdata/recovery-removed-v3.json").absolutePath)
    systemProperty("chainVectors", rootProject.file("../internal/deviceauth/testdata/chain-v3.json").absolutePath)
    systemProperty("v2Vectors", rootProject.file("../internal/e2e/testdata/v2-vectors.json").absolutePath)
    systemProperty("kotlinVectors", rootProject.file("../internal/e2e/testdata/kotlin-vectors.json").absolutePath)
    // ./gradlew :core:test -PupdateVectors rewrites kotlin-vectors.json.
    if (project.hasProperty("updateVectors")) systemProperty("updateVectors", "1")
}
